"""Regenerates src/config/blocky_prop_models.gd from art/props-3d/props/blocky/manifest.json.

    python3 tools/props/emit_models.py [MANIFEST.json [OUT.gd]]
"""
import json
import sys

manifest_path = sys.argv[1] if len(sys.argv) > 1 else "art/props-3d/props/blocky/manifest.json"
out_path = sys.argv[2] if len(sys.argv) > 2 else "src/config/blocky_prop_models.gd"
manifest = json.load(open(manifest_path))
lines = ["class_name BlockyPropModels", "extends RefCounted", "",
         "## GENERATED by tools/props/build_blocky_props.py (see tools/props/README.md):",
         "## the Minecraft-style rebuilds of props, by catalogue type.",
         "## PropModelCatalog.USE_BLOCKY_PROPS switches them on; the old models stay as the fallback.", "",
         "const MODELS := {"]
for name, files in manifest.items():
    paths = ", ".join('"res://art/props-3d/props/blocky/%s"' % f for f in files)
    lines.append('\t"%s": [%s],' % (name, paths))
lines.append("}")
open(out_path, "w").write("\n".join(lines) + "\n")
print("wrote", out_path, len(manifest), "types")
